window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8d0c95daf747c74c"]={"versions": [{"id": "FIG-8d0c95daf747c74c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden-Aktivitätsdiagramm (AUTOSAR Methodology Work Product / Activity View) zur Definition des internen Verhaltens von Basissoftware-Modulen innerhalb des BSW-Entwicklungsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>Basic Software Designer</code> (Akteur/Bearbeiter)\n</li><li><strong>Aktivität</strong>: <code>Define BSW Behavior</code> (zentraler Prozessschritt)\n</li><li><strong>Eingangsartefakte</strong>:\n<ul class=\"fig-list\"><li><code>BSW Standard Package</code> («input», Kardinalität 0..1, Paket-/Dokumentensymbol oben links)\n</li><li><code>Basic Software Module Description</code> (abgeschnitten als <code>Basic Soft...</code> dargestellt; «input», Kardinalität 1, Dokumentensymbol unten links)\n</li></ul>\n</li><li><strong>Ausgangsartefakt</strong>:\n<ul class=\"fig-list\"><li><code>Basic Software Module Internal Behavior</code> («output», Kardinalität 1, Dokumentensymbol rechts)\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>Basic Software Designer</code> --(«performs», Zielkardinalität 1)--&gt; <code>Define BSW Behavior</code>\n</li><li><code>BSW Standard Package</code> --(«input»)--&gt; <code>Define BSW Behavior</code>\n</li><li><code>Basic Software Module Description</code> --(«input»)--&gt; <code>Define BSW Behavior</code>\n</li><li><code>Define BSW Behavior</code> --(«output»)--&gt; <code>Basic Software Module Internal Behavior</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Basic Software Designer</code> führt die Aktivität <code>Define BSW Behavior</code> aus.\n</li><li>Als obligatorische Eingabe (<code>1</code>) dient die Beschreibung des Basissoftware-Moduls (<code>Basic Software Module Description</code>).\n</li><li>Optional (<code>0..1</code>) fließt ein standardisiertes Paket (<code>BSW Standard Package</code>) als Vorgabe oder Vorlage ein.\n</li><li>Als Ergebnis der Aktivität wird genau eine interne Verhaltensbeschreibung (<code>Basic Software Module Internal Behavior</code>, Kardinalität <code>1</code>) erzeugt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität ist essenzieller Bestandteil der AUTOSAR-Methodik zur Spezifikation von BSW-Modulen. Das resultierende <code>Basic Software Module Internal Behavior</code> spezifiziert unter anderem Runnable Entities, Scheduling-Events und Schnittstellenanbindungen an das BSW Scheduler / RTE-Umfeld und bildet die formale Grundlage für die BSW-Konfiguration und Code-Generierung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-94d903d1afddaf12", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden-Aktivitätsdiagramm (AUTOSAR Methodology Work Product / Activity View) zur Definition des internen Verhaltens von Basissoftware-Modulen innerhalb des BSW-Entwicklungsprozesses der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>Basic Software Designer</code> (Akteur/Bearbeiter)\n</li><li><strong>Aktivität</strong>: <code>Define BSW Behavior</code> (zentraler Prozessschritt)\n</li><li><strong>Eingangsartefakte</strong>:\n<ul class=\"fig-list\"><li><code>BSW Standard Package</code> («input», Kardinalität 0..1, Paket-/Dokumentensymbol oben links)\n</li><li><code>Basic Software Module Description</code> (abgeschnitten als <code>Basic Soft...</code> dargestellt; «input», Kardinalität 1, Dokumentensymbol unten links)\n</li></ul>\n</li><li><strong>Ausgangsartefakt</strong>:\n<ul class=\"fig-list\"><li><code>Basic Software Module Internal Behavior</code> («output», Kardinalität 1, Dokumentensymbol rechts)\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>Basic Software Designer</code> --(«performs», Zielkardinalität 1)--&gt; <code>Define BSW Behavior</code>\n</li><li><code>BSW Standard Package</code> --(«input»)--&gt; <code>Define BSW Behavior</code>\n</li><li><code>Basic Software Module Description</code> --(«input»)--&gt; <code>Define BSW Behavior</code>\n</li><li><code>Define BSW Behavior</code> --(«output»)--&gt; <code>Basic Software Module Internal Behavior</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Basic Software Designer</code> führt die Aktivität <code>Define BSW Behavior</code> aus.\n</li><li>Als obligatorische Eingabe (<code>1</code>) dient die Beschreibung des Basissoftware-Moduls (<code>Basic Software Module Description</code>).\n</li><li>Optional (<code>0..1</code>) fließt ein standardisiertes Paket (<code>BSW Standard Package</code>) als Vorgabe oder Vorlage ein.\n</li><li>Als Ergebnis der Aktivität wird genau eine interne Verhaltensbeschreibung (<code>Basic Software Module Internal Behavior</code>, Kardinalität <code>1</code>) erzeugt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität ist essenzieller Bestandteil der AUTOSAR-Methodik zur Spezifikation von BSW-Modulen. Das resultierende <code>Basic Software Module Internal Behavior</code> spezifiziert unter anderem Runnable Entities, Scheduling-Events und Schnittstellenanbindungen an das BSW Scheduler / RTE-Umfeld und bildet die formale Grundlage für die BSW-Konfiguration und Code-Generierung.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8d0c95daf747c74c", "to": "FIG-94d903d1afddaf12", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
